-- Spielsprache erkennen: Azeroth Survivors hat eine eigene Sprachwahl. Wir schauen,
-- in welcher Sprache die Namen im Schadensmeter des Spiels stehen.
local detected
local lastTry = -100
function PhantomUI_Lang()
	if detected then
		return detected
	end
	-- Einmal erkannte Sprache gilt auch vor dem naechsten Lauf (Menues, Plan).
	if PhantomUIDB and PhantomUIDB.lang then
		detected = PhantomUIDB.lang
		if PhantomUI_TrimLanguages then
			PhantomUI_TrimLanguages(detected)
		end
		return detected
	end
	local now = GetTime and GetTime() or 0
	if now - lastTry < 5 then
		return "enUS"
	end
	lastTry = now
	local lines = AZS_GetMeter and AZS_GetMeter()
	if type(lines) ~= "table" or table.getn(lines) == 0 then
		return "enUS"
	end
	local best, bestCount, enCount = nil, 0, 0
	local lang, map
	for lang, map in pairs(PhantomUI_SpellLocale) do
		local values = {}
		local en, name
		for en, name in pairs(map) do
			values[name] = true
		end
		local count = 0
		local i
		for i = 1, table.getn(lines) do
			if lines[i].name and values[lines[i].name] then
				count = count + 1
			end
		end
		if count > bestCount then
			best, bestCount = lang, count
		end
	end
	if best and bestCount >= 2 then
		detected = best
		if PhantomUIDB then
			PhantomUIDB.lang = best
		end
		if PhantomUI_TrimLanguages then
			PhantomUI_TrimLanguages(best)
		end
	elseif table.getn(lines) >= 4 then
		detected = "enUS"
	end
	return detected or "enUS"
end

function PhantomUI_LocalName(english)
	local lang = PhantomUI_Lang()
	local map = PhantomUI_SpellLocale[lang]
	return map and map[english] or english
end

-- Nur die eigene Sprache (und Englisch fuers Kampflog) im Speicher behalten.
-- Weniger Speicher = kuerzere Pausen der Speicherbereinigung (Ruckler).
local trimmed = false
function PhantomUI_TrimLanguages(lang)
	if trimmed or not lang then
		return
	end
	trimmed = true
	local function keepOnly(t)
		if type(t) ~= "table" then
			return
		end
		local drop = {}
		local k
		for k in pairs(t) do
			if k ~= lang and k ~= "enUS" then
				table.insert(drop, k)
			end
		end
		for i = 1, table.getn(drop) do
			t[drop[i]] = nil
		end
	end
	-- Symbol-Tabelle: Namen anderer Sprachen entfernen. Behalten wird alles,
	-- was Englisch ist, zur eigenen Sprache gehoert oder nirgends zugeordnet ist.
	if PhantomUI_SpellLocale and AZSSpellMeterLocaleIcons then
		local keep, foreign = {}, {}
		local l, map, en, name
		for l, map in pairs(PhantomUI_SpellLocale) do
			for en, name in pairs(map) do
				keep[en] = true
				if l == lang then
					keep[name] = true
				else
					foreign[name] = true
				end
			end
		end
		local drop = {}
		for name in pairs(AZSSpellMeterLocaleIcons) do
			if foreign[name] and not keep[name] then
				table.insert(drop, name)
			end
		end
		for i = 1, table.getn(drop) do
			AZSSpellMeterLocaleIcons[drop[i]] = nil
		end
	end
	keepOnly(PhantomUI_SpellLocale)
	keepOnly(PhantomUI_StatLabels)
	keepOnly(PhantomUI_StatTips)
	keepOnly(PhantomUI_AlertTexts)
	local function trimNames(list)
		if type(list) ~= "table" then
			return
		end
		for _, entries in pairs(list) do
			for i = 1, table.getn(entries) do
				keepOnly(entries[i].names)
				keepOnly(entries[i].desc)
			end
		end
	end
	trimNames(PhantomUI_PlanData)
	trimNames(PhantomUI_PlanItems)
end
